function noiseBlob(graphic, x, y, r0, delta, noiseStrength, resolution) {
    let r, theta;
    graphic.beginShape();
    for (let i = 0; i < 360; i += (Math.max(0.001, Math.abs(resolution)) || 1)) {
      theta = radians(i);
      r = r0 * (1 + noiseStrength*noise(delta+cos(theta), delta+sin(theta)));
      graphic.vertex(x + r*cos(theta), y + r*sin(theta));
    }
    graphic.endShape(CLOSE);
  }

  function createBackground() {
    let delta = 0.2;
    bg.background(255,245,240);
    fill(250, 0, 0);
    bg.fill(230, 200, 150);
    noiseBlob(
      bg,
      width/2 + height*random(-delta, delta),
      height/2 + height*random(-delta, delta),
      height/7,
      random(TWO_PI),
      1,
      1
    );
    bg.fill(232, 142, 97);
