function createLeaf(pos, size, opening, modLength, distortion, steps) {
    let baseMMag = modLength.base * size.h;
    let base = {};
    base.p = createVector(0, 0);
    base.m = {};
    base.m.right = constructVector(distortion.leafAngle + opening.base, baseMMag, base.p);
    base.m.left = constructVector(distortion.leafAngle - opening.base, baseMMag, base.p);
    base.m.center = constructVector(distortion.leafAngle, baseMMag, base.p);

    let apexMMag = modLength.apex * size.h;
    let apex = {};
    apex.p = createVector(size.h, 0);
    apex.m = {};
    apex.m.left = constructVector(PI - distortion.leafAngle + opening.apex, apexMMag, apex.p);
    apex.m.right = constructVector(PI - distortion.leafAngle - opening.apex, apexMMag, apex.p);
    apex.m.center = constructVector(PI - distortion.leafAngle, apexMMag, apex.p);

    let baseMarginMag = modLength.baseMargin * size.h;
    let apexMarginMag = modLength.apexMargin * size.h;
    let marginPos = distortion.dMargin * size.h;
    let marginW = 0.5 * size.w;
    let dAngleW = size.w * sin(distortion.leafAngle);
    let margin = {};
    margin.left = {};
    margin.left.p = createVector(marginPos, -marginW + dAngleW);
    margin.left.m = {};
    margin.left.m.before = constructVector(PI + distortion.leafAngle - opening.margin, baseMarginMag, margin.left.p);
    margin.left.m.after = constructVector(distortion.leafAngle - opening.margin, apexMarginMag, margin.left.p);
    margin.right = {};
    margin.right.p = createVector(marginPos, marginW + dAngleW);
    margin.right.m = {};
    margin.right.m.before = constructVector(distortion.leafAngle + opening.margin, apexMarginMag, margin.right.p);
    margin.right.m.after = constructVector(PI + distortion.leafAngle + opening.margin, baseMarginMag, margin.right.p);

    let midrib = {};
    midrib.p = createVector(marginPos, dAngleW);
    midrib.m = {};
    midrib.m.before = p5.Vector.fromAngle(PI + distortion.leafAngle).setMag(apexMarginMag).add(midrib.p);
    midrib.m.after = p5.Vector.fromAngle(distortion.leafAngle).setMag(baseMarginMag).add(midrib.p);

    for (let i = 1; i >= 0; i -= 1/steps) {
      drawLeaf(main, false, pos, base, margin, midrib, apex, i);
      drawLeaf(debug, true, pos, base, margin, midrib, apex, i);
    }
  }

  function drawLeaf(graphic, isDebug, pos, base, margin, midrib, apex, i) {
    graphic.push();
    graphic.translate(pos.x, pos.y);
    graphic.rotate(pos.theta);

    graphic.beginShape();
    bezierStep(
      base.p,
      p5.Vector.lerp(base.m.center, base.m.left, i),
      p5.Vector.lerp(midrib.m.before, margin.left.m.before, i),
      p5.Vector.lerp(midrib.p, margin.left.p, i),
      true /*isBeginning*/,
      graphic,
      isDebug,
    ); 
    bezierStep(
      p5.Vector.lerp(midrib.p, margin.left.p, i),
      p5.Vector.lerp(midrib.m.after, margin.left.m.after, i),
      p5.Vector.lerp(apex.m.center, apex.m.left, i),
      apex.p,
      false /*isBeginning*/,
      graphic,
      isDebug
    );
    bezierStep(
      apex.p,
      p5.Vector.lerp(apex.m.center, apex.m.right, i),
      p5.Vector.lerp(midrib.m.after, margin.right.m.before, i),
      p5.Vector.lerp(midrib.p, margin.right.p, i),
      false /*isBeginning*/,
      graphic,
      isDebug
    );
    bezierStep(
      p5.Vector.lerp(midrib.p, margin.right.p, i),
      p5.Vector.lerp(midrib.m.before, margin.right.m.after, i),
      p5.Vector.lerp(base.m.center, base.m.right, i),
      base.p,
      false /*isBeginning*/,
      graphic,
      isDebug
    ); 
    graphic.endShape();

    graphic.pop();
  }

  function bezierStep(a, b, c, d, isBeginning, graphic, isDebug) {
    if (!isDebug) {
      graphic.strokeWeight(0.001*height);
      graphic.stroke(hue, saturation, brightness);
      graphic.fill(hue, saturation, random(50, 60));
    }

    if (isBeginning) {
      graphic.vertex(a.x, a.y);
    }
    graphic.bezierVertex(b.x, b.y, c.x, c.y, d.x, d.y);

    if (isDebug) {  
      graphic.line(a.x, a.y, b.x, b.y);
      graphic.line(c.x, c.y, d.x, d.y);

      let diam = 0.01*height;
      graphic.circle(a.x, a.y, diam);
      graphic.circle(b.x, b.y, diam);  
      graphic.circle(c.x, c.y, diam);
      graphic.circle(d.x, d.y, diam);
    }
  }

  function constructVector(angle, magnitude, dislocation) {
    return p5.Vector.fromAngle(angle).setMag(magnitude).add(dislocation);
  }

